import type{PoolClient}from'pg';import{sha256Canonical}from'../core/hash.js';
export async function insertFact(c:PoolClient,args:any):Promise<string>{const doc={featureCode:args.featureCode,value:args.numericValue??args.textValue??null,unit:args.unit,sourceRole:args.sourceRole,sourceVintage:args.sourceVintage,geography:args.geographyScope,missingness:args.missingness??'PRESENT',suppressionFlag:args.suppressionFlag??null};const q=await c.query<{fact_id:string}>(`INSERT INTO zsl.zsl3_source_facts(build_run_id,location_id,feature_code,numeric_value,text_value,unit,evidence_class,source_role,source_binding_id,source_record_id,source_record_sha256,source_variable_code,source_vintage,geography_scope,source_geography_type,missingness_state,suppression_flag,fact_document,fact_sha256) VALUES($1,$2,$3,$4,$5,$6,'SOURCE_FACT',$7,$8,$9,$10,$11,$12,$13,$13,$14,$15,$16::jsonb,$17) RETURNING fact_id::text`,[args.run,args.locationId,args.featureCode,args.numericValue??null,args.textValue??null,args.unit,args.sourceRole,args.binding.source_binding_id,args.raw.record_id,args.raw.record_sha256,args.sourceVariableCode??null,args.binding.source_vintage,args.binding.source_geography,args.missingness??'PRESENT',args.suppressionFlag??null,JSON.stringify(doc),sha256Canonical(doc)]);const factId=q.rows[0]!.fact_id;const lin={factId,rawRecordId:args.raw.record_id,sourceBindingId:args.binding.source_binding_id,releaseId:args.binding.release_id,ingestRunId:args.binding.ingest_run_id,certificationRunId:args.binding.certification_run_id};await c.query(`INSERT INTO zsl.zsl3_fact_lineage(build_run_id,fact_id,source_binding_id,source_release_id,ingest_run_id,certification_run_id,raw_record_id,raw_record_sha256,lineage_document,lineage_sha256) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9::jsonb,$10)`,[args.run,factId,args.binding.source_binding_id,args.binding.release_id,args.binding.ingest_run_id,args.binding.certification_run_id,args.raw.record_id,args.raw.record_sha256,JSON.stringify(lin),sha256Canonical(lin)]);return factId}
export async function certifiedRows(c:PoolClient,b:any):Promise<any[]>{return(await c.query<any>(`SELECT rr.record_id::text,rr.record,rr.record_sha256 FROM zsl.release_record_memberships m JOIN zsl_raw.raw_records rr ON rr.record_id=m.record_id WHERE m.release_id=$1 AND m.ingest_run_id=$2 ORDER BY m.ordinal`,[b.release_id,b.ingest_run_id])).rows}
